 static int tests;static void Check(bool ok){++tests;if(!ok)throw new Exception("Failed check "+tests);}static byte[] Hex(string x){var b=new byte[x.Length/2];for(int i=0;i<b.Length;++i)b[i]=Convert.ToByte(x.Substring(i*2,2),16);return b;}
 static void Main(){long image=0x140000000,relay=image+0x70000000,target=0x7fff0000e620;var region=new byte[1561];new Random(7).NextBytes(region);var original=Hex("e8f0ba0000");Array.Copy(original,0,region,0x4b,5);Check(image+0x360128b+5+BitConverter.ToInt32(original,1)==image+0x360cd80);var plain=(byte[])region.Clone();Check(Object.ReferenceEquals(region,ExtensionsPregame.Normalize((a,n)=>null,image,region,null)));
 var call=new byte[5];call[0]=0xe8;Array.Copy(BitConverter.GetBytes((int)(relay-(image+0x360128b+5))),0,call,1,4);Array.Copy(call,0,region,0x4b,5);var wrapped=(byte[])region.Clone();var stub=new byte[12];stub[0]=0x48;stub[1]=0xb8;Array.Copy(BitConverter.GetBytes(target),0,stub,2,8);stub[10]=0xff;stub[11]=0xe0;var body=Hex("4157415641554154555756534881ecc80000004889ce488d0d97470200e8fe67ffff8b0518da010083f8ff0f85570100008b05e5b2030085c00f8549010000448b1d22ea03008b1dbcb603004585db741f8b057dda010083f8ff74148b158ada");Func<long,int,byte[]> read=(a,n)=>a==relay&&n==12?(byte[])stub.Clone():a==target&&n==body.Length?(byte[])body.Clone():null;Func<long,bool> owner=a=>a==target;
 var normalized=ExtensionsPregame.Normalize(read,image,region,owner);for(int i=0;i<plain.Length;++i){Check(normalized[i]==plain[i]);Check(region[i]==wrapped[i]);}
 for(int bad=0;bad<5;++bad){var b=(byte[])body.Clone();var t=(byte[])stub.Clone();if(bad==0)stub[0]^=1;if(bad==1)body[50]^=1;if(bad==2)stub[11]^=1;bool rejected=false;try{ExtensionsPregame.Normalize(read,image,region,bad==3?(Func<long,bool>)(a=>false):bad==4?null:owner);}catch(InvalidOperationException){rejected=true;}Check(rejected);body=b;stub=t;}
 Console.WriteLine("PASS "+tests+" exact original/rel32/relay/body/owner checks, immutable local normalization and malformed/unknown wrapper rejection; no game access.");}
